PRODUCTION_SOURCE = '"""\nOLA-035\nOracle Atomic Market Lineage Batch Router\n\nAtomic cohort boundary above OLA-034.\n\nPurpose:\n- accept one ordered canonical market_snapshot cohort\n- preflight the entire cohort before mutating live lineage state\n- reject duplicate observation identities within the batch\n- reject duplicate source + market identities within the same cohort\n- validate every frame against an isolated clone of current lineage state\n- commit the entire cohort only after full preflight succeeds\n- preserve deterministic ordered receipts and per-market lineage continuity\n\nThis boundary owns no persistence, intelligence interpretation, scoring,\nalerting, Q Series handoff, authorization, or execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom copy import deepcopy\nfrom dataclasses import dataclass\nfrom datetime import datetime\nfrom typing import Iterable\n\nfrom .oracle_live_market_lineage_pipeline_bridge import (\n    LiveMarketLineagePipelineContractError,\n    LiveMarketLineagePipelineInvariantError,\n    LiveMarketLineagePipelineReceipt,\n    OracleLiveMarketLineagePipelineBridge,\n)\nfrom .oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n)\n\n\nSCHEMA_VERSION = "OLA-035"\nENGINE_ID = "OLA-035"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass AtomicMarketLineageBatchContractError(ValueError):\n    """Raised when OLA-035 batch input is malformed."""\n\n\nclass AtomicMarketLineageBatchInvariantError(RuntimeError):\n    """Raised when permanent OLA-035 invariants are violated."""\n\n\n@dataclass(frozen=True, slots=True)\nclass AtomicMarketLineageBatchFrame:\n    observation: CanonicalObservation\n    frame_observed_at: datetime\n\n\n@dataclass(frozen=True, slots=True)\nclass AtomicMarketLineageBatchReceipt:\n    schema_version: str\n    engine_id: str\n    status: str\n    batch_frame_count: int\n    batch_market_count: int\n    ledger_market_count_before: int\n    ledger_record_count_before: int\n    ledger_market_count_after: int\n    ledger_record_count_after: int\n    transition_count: int\n    receipts: tuple[LiveMarketLineagePipelineReceipt, ...]\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise AtomicMarketLineageBatchInvariantError(\n                "schema version invariant violated"\n            )\n        if self.engine_id != ENGINE_ID:\n            raise AtomicMarketLineageBatchInvariantError(\n                "engine identity invariant violated"\n            )\n        if self.status != "committed":\n            raise AtomicMarketLineageBatchInvariantError(\n                "successful batch receipt must be committed"\n            )\n        if self.batch_frame_count <= 0:\n            raise AtomicMarketLineageBatchInvariantError(\n                "batch frame count must be positive"\n            )\n        if self.batch_market_count <= 0:\n            raise AtomicMarketLineageBatchInvariantError(\n                "batch market count must be positive"\n            )\n        if len(self.receipts) != self.batch_frame_count:\n            raise AtomicMarketLineageBatchInvariantError(\n                "receipt count must equal batch frame count"\n            )\n        if (\n            self.ledger_record_count_after\n            - self.ledger_record_count_before\n            != self.batch_frame_count\n        ):\n            raise AtomicMarketLineageBatchInvariantError(\n                "committed record delta must equal batch frame count"\n            )\n        if self.transition_count != sum(\n            1\n            for receipt in self.receipts\n            if receipt.transition_detected\n        ):\n            raise AtomicMarketLineageBatchInvariantError(\n                "transition count invariant violated"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise AtomicMarketLineageBatchInvariantError(\n                "OLA-035 read-only authority invariants violated"\n            )\n\n\nclass OracleAtomicMarketLineageBatchRouter:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        bridge: OracleLiveMarketLineagePipelineBridge | None = None,\n    ) -> None:\n        self._bridge = (\n            bridge\n            if bridge is not None\n            else OracleLiveMarketLineagePipelineBridge()\n        )\n\n        if not isinstance(\n            self._bridge,\n            OracleLiveMarketLineagePipelineBridge,\n        ):\n            raise AtomicMarketLineageBatchContractError(\n                "bridge must be an OLA-034 "\n                "OracleLiveMarketLineagePipelineBridge"\n            )\n\n    @property\n    def bridge(self) -> OracleLiveMarketLineagePipelineBridge:\n        return self._bridge\n\n    def route(\n        self,\n        *,\n        frames: Iterable[AtomicMarketLineageBatchFrame],\n    ) -> AtomicMarketLineageBatchReceipt:\n        normalized_frames = tuple(frames)\n\n        if not normalized_frames:\n            raise AtomicMarketLineageBatchContractError(\n                "batch must contain at least one frame"\n            )\n\n        observation_ids: set[str] = set()\n        market_keys: set[tuple[str, str]] = set()\n\n        for frame in normalized_frames:\n            if not isinstance(\n                frame,\n                AtomicMarketLineageBatchFrame,\n            ):\n                raise AtomicMarketLineageBatchContractError(\n                    "batch frames must be "\n                    "AtomicMarketLineageBatchFrame records"\n                )\n\n            observation = frame.observation\n\n            if not isinstance(observation, CanonicalObservation):\n                raise AtomicMarketLineageBatchContractError(\n                    "batch observation must be canonical"\n                )\n            if observation.observation_type != "market_snapshot":\n                raise AtomicMarketLineageBatchContractError(\n                    "batch accepts only market_snapshot observations"\n                )\n\n            observation_id = observation.observation_id\n\n            if observation_id in observation_ids:\n                raise AtomicMarketLineageBatchContractError(\n                    "duplicate observation_id within batch"\n                )\n\n            source_market_id = observation.payload.get(\n                "source_market_id"\n            )\n\n            if not isinstance(source_market_id, str):\n                raise AtomicMarketLineageBatchContractError(\n                    "source_market_id must be present in observation payload"\n                )\n\n            source_market_id = source_market_id.strip()\n\n            if not source_market_id:\n                raise AtomicMarketLineageBatchContractError(\n                    "source_market_id must not be empty"\n                )\n\n            market_key = (\n                observation.source_id,\n                source_market_id,\n            )\n\n            if market_key in market_keys:\n                raise AtomicMarketLineageBatchContractError(\n                    "duplicate source + market identity within batch"\n                )\n\n            observation_ids.add(observation_id)\n            market_keys.add(market_key)\n\n        before_market_count = self._bridge.ledger.market_count\n        before_record_count = self._bridge.ledger.record_count\n\n        try:\n            preflight_bridge = deepcopy(self._bridge)\n        except Exception as exc:\n            raise AtomicMarketLineageBatchInvariantError(\n                f"unable to clone live lineage state for preflight: {exc}"\n            ) from exc\n\n        try:\n            for frame in normalized_frames:\n                preflight_bridge.process(\n                    observation=frame.observation,\n                    frame_observed_at=frame.frame_observed_at,\n                )\n        except LiveMarketLineagePipelineContractError as exc:\n            raise AtomicMarketLineageBatchContractError(\n                f"batch preflight rejected cohort: {exc}"\n            ) from exc\n        except LiveMarketLineagePipelineInvariantError as exc:\n            raise AtomicMarketLineageBatchInvariantError(\n                f"batch preflight invariant failed: {exc}"\n            ) from exc\n\n        if self._bridge.ledger.market_count != before_market_count:\n            raise AtomicMarketLineageBatchInvariantError(\n                "preflight mutated live ledger market count"\n            )\n        if self._bridge.ledger.record_count != before_record_count:\n            raise AtomicMarketLineageBatchInvariantError(\n                "preflight mutated live ledger record count"\n            )\n\n        receipts: list[LiveMarketLineagePipelineReceipt] = []\n\n        for frame in normalized_frames:\n            try:\n                receipts.append(\n                    self._bridge.process(\n                        observation=frame.observation,\n                        frame_observed_at=frame.frame_observed_at,\n                    )\n                )\n            except LiveMarketLineagePipelineContractError as exc:\n                raise AtomicMarketLineageBatchInvariantError(\n                    "commit diverged from successful preflight: "\n                    f"{exc}"\n                ) from exc\n            except LiveMarketLineagePipelineInvariantError as exc:\n                raise AtomicMarketLineageBatchInvariantError(\n                    "commit invariant diverged from preflight: "\n                    f"{exc}"\n                ) from exc\n\n        receipt = AtomicMarketLineageBatchReceipt(\n            schema_version=SCHEMA_VERSION,\n            engine_id=ENGINE_ID,\n            status="committed",\n            batch_frame_count=len(normalized_frames),\n            batch_market_count=len(market_keys),\n            ledger_market_count_before=before_market_count,\n            ledger_record_count_before=before_record_count,\n            ledger_market_count_after=self._bridge.ledger.market_count,\n            ledger_record_count_after=self._bridge.ledger.record_count,\n            transition_count=sum(\n                1\n                for item in receipts\n                if item.transition_detected\n            ),\n            receipts=tuple(receipts),\n            read_only=READ_ONLY,\n            execution_allowed=EXECUTION_ALLOWED,\n            execution_adapter_resolved=EXECUTION_ADAPTER_RESOLVED,\n            execution_adapter_invoked=EXECUTION_ADAPTER_INVOKED,\n            trade_authorization_allowed=TRADE_AUTHORIZATION_ALLOWED,\n            order_placement_allowed=ORDER_PLACEMENT_ALLOWED,\n            funds_moved=FUNDS_MOVED,\n            portfolio_mutated=PORTFOLIO_MUTATED,\n        )\n\n        receipt.assert_invariants()\n        return receipt\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_atomic_market_lineage_batch_router import (\n    AtomicMarketLineageBatchContractError,\n    AtomicMarketLineageBatchFrame,\n    OracleAtomicMarketLineageBatchRouter,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(2026, 7, 14, 8, 0, 0, tzinfo=timezone.utc)\nT2 = datetime(2026, 7, 14, 8, 0, 10, tzinfo=timezone.utc)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi." + market_id + "." + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id="batch.ola.035." + frame_id,\n    )\n\n\ndef build_five_market_batch(\n    *,\n    frame_suffix,\n    observed_at,\n    changed_market=None,\n):\n    frames = []\n\n    for index in range(1, 6):\n        market_id = f"KXTEST-COHORT-{index}"\n        yes_ask = (\n            "0.7770"\n            if changed_market == market_id\n            else "0.6140"\n        )\n\n        frames.append(\n            AtomicMarketLineageBatchFrame(\n                observation=build_observation(\n                    market_id=market_id,\n                    frame_id=f"{frame_suffix}-{index}",\n                    yes_ask=yes_ask,\n                ),\n                frame_observed_at=observed_at,\n            )\n        )\n\n    return tuple(frames)\n\n\ndef run_first_cohort_test():\n    router = OracleAtomicMarketLineageBatchRouter()\n\n    receipt = router.route(\n        frames=build_five_market_batch(\n            frame_suffix="f1",\n            observed_at=T1,\n        )\n    )\n\n    assert receipt.status == "committed"\n    assert receipt.batch_frame_count == 5\n    assert receipt.batch_market_count == 5\n    assert receipt.ledger_market_count_before == 0\n    assert receipt.ledger_record_count_before == 0\n    assert receipt.ledger_market_count_after == 5\n    assert receipt.ledger_record_count_after == 5\n    assert receipt.transition_count == 0\n    assert len(receipt.receipts) == 5\n\n    return router, receipt\n\n\ndef run_second_same_cohort_test():\n    router, _ = run_first_cohort_test()\n\n    receipt = router.route(\n        frames=build_five_market_batch(\n            frame_suffix="f2",\n            observed_at=T2,\n        )\n    )\n\n    assert receipt.batch_frame_count == 5\n    assert receipt.ledger_market_count_before == 5\n    assert receipt.ledger_record_count_before == 5\n    assert receipt.ledger_market_count_after == 5\n    assert receipt.ledger_record_count_after == 10\n    assert receipt.transition_count == 0\n\n    for item in receipt.receipts:\n        assert item.consecutive_frame_count == 2\n        assert item.dwell_seconds == "10.000000"\n\n    return router, receipt\n\n\ndef run_single_market_transition_cohort_test():\n    router, _ = run_first_cohort_test()\n\n    receipt = router.route(\n        frames=build_five_market_batch(\n            frame_suffix="f2-change",\n            observed_at=T2,\n            changed_market="KXTEST-COHORT-3",\n        )\n    )\n\n    assert receipt.transition_count == 1\n\n    changed = [\n        item\n        for item in receipt.receipts\n        if item.transition_detected\n    ]\n\n    assert len(changed) == 1\n    assert changed[0].source_market_id == "KXTEST-COHORT-3"\n    assert changed[0].consecutive_frame_count == 1\n    assert changed[0].dwell_seconds == "0.000000"\n\n    unchanged = [\n        item\n        for item in receipt.receipts\n        if not item.transition_detected\n    ]\n\n    assert len(unchanged) == 4\n\n    for item in unchanged:\n        assert item.consecutive_frame_count == 2\n        assert item.dwell_seconds == "10.000000"\n\n    return router, receipt\n\n\ndef run_atomic_preflight_failure_test():\n    router, _ = run_first_cohort_test()\n\n    before_records = router.bridge.ledger.records()\n    before_heads = router.bridge.ledger.heads()\n\n    invalid_frames = list(\n        build_five_market_batch(\n            frame_suffix="invalid",\n            observed_at=T2,\n        )\n    )\n\n    invalid_frames[-1] = AtomicMarketLineageBatchFrame(\n        observation=invalid_frames[-1].observation,\n        frame_observed_at=datetime(\n            2026,\n            7,\n            14,\n            7,\n            59,\n            59,\n            tzinfo=timezone.utc,\n        ),\n    )\n\n    try:\n        router.route(frames=invalid_frames)\n        raise AssertionError(\n            "invalid cohort must fail closed before commit"\n        )\n    except AtomicMarketLineageBatchContractError:\n        pass\n\n    assert router.bridge.ledger.records() == before_records\n    assert router.bridge.ledger.heads() == before_heads\n    assert router.bridge.ledger.record_count == 5\n\n\ndef run_duplicate_market_identity_test():\n    router = OracleAtomicMarketLineageBatchRouter()\n\n    observation_one = build_observation(\n        market_id="KXTEST-DUP-MARKET",\n        frame_id="one",\n    )\n    observation_two = build_observation(\n        market_id="KXTEST-DUP-MARKET",\n        frame_id="two",\n    )\n\n    frames = (\n        AtomicMarketLineageBatchFrame(\n            observation=observation_one,\n            frame_observed_at=T1,\n        ),\n        AtomicMarketLineageBatchFrame(\n            observation=observation_two,\n            frame_observed_at=T1,\n        ),\n    )\n\n    try:\n        router.route(frames=frames)\n        raise AssertionError(\n            "duplicate market identity within cohort must fail closed"\n        )\n    except AtomicMarketLineageBatchContractError:\n        pass\n\n    assert router.bridge.ledger.record_count == 0\n\n\ndef run_duplicate_observation_identity_test():\n    router = OracleAtomicMarketLineageBatchRouter()\n    observation = build_observation(\n        market_id="KXTEST-DUP-OBS",\n        frame_id="one",\n    )\n\n    frames = (\n        AtomicMarketLineageBatchFrame(\n            observation=observation,\n            frame_observed_at=T1,\n        ),\n        AtomicMarketLineageBatchFrame(\n            observation=observation,\n            frame_observed_at=T1,\n        ),\n    )\n\n    try:\n        router.route(frames=frames)\n        raise AssertionError(\n            "duplicate observation identity must fail closed"\n        )\n    except AtomicMarketLineageBatchContractError:\n        pass\n\n    assert router.bridge.ledger.record_count == 0\n\n\ndef run_deterministic_batch_replay_test():\n    first = OracleAtomicMarketLineageBatchRouter()\n    second = OracleAtomicMarketLineageBatchRouter()\n\n    batch_one = build_five_market_batch(\n        frame_suffix="r1",\n        observed_at=T1,\n    )\n    batch_two = build_five_market_batch(\n        frame_suffix="r2",\n        observed_at=T2,\n        changed_market="KXTEST-COHORT-4",\n    )\n\n    first_receipts = (\n        first.route(frames=batch_one),\n        first.route(frames=batch_two),\n    )\n    second_receipts = (\n        second.route(frames=batch_one),\n        second.route(frames=batch_two),\n    )\n\n    assert first_receipts == second_receipts\n    assert (\n        first.bridge.ledger.records()\n        == second.bridge.ledger.records()\n    )\n\n    return first_receipts\n\n\ndef main():\n    _, first_receipt = run_first_cohort_test()\n    _, same_receipt = run_second_same_cohort_test()\n    _, changed_receipt = run_single_market_transition_cohort_test()\n\n    run_atomic_preflight_failure_test()\n    run_duplicate_market_identity_test()\n    run_duplicate_observation_identity_test()\n\n    replay_receipts = run_deterministic_batch_replay_test()\n\n    result = {\n        "schema_version": first_receipt.schema_version,\n        "engine_id": first_receipt.engine_id,\n        "status": "passed",\n        "ola_034_pipeline_bridge_consumed": True,\n        "five_market_cohort_routed": (\n            first_receipt.batch_market_count == 5\n        ),\n        "full_batch_preflight_before_commit": True,\n        "preflight_isolated_from_live_ledger": True,\n        "atomic_failure_preserves_live_lineage": True,\n        "same_five_market_cohort_dwell_advanced": (\n            same_receipt.ledger_record_count_after == 10\n        ),\n        "single_market_transition_isolated": (\n            changed_receipt.transition_count == 1\n        ),\n        "ordered_batch_receipts_preserved": True,\n        "duplicate_market_identity_fails_closed": True,\n        "duplicate_observation_identity_fails_closed": True,\n        "deterministic_batch_replay_valid": (\n            len(replay_receipts) == 2\n        ),\n        "no_persistence_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": first_receipt.read_only,\n        "execution_allowed": first_receipt.execution_allowed,\n        "execution_adapter_resolved": (\n            first_receipt.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            first_receipt.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            first_receipt.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            first_receipt.order_placement_allowed\n        ),\n        "funds_moved": first_receipt.funds_moved,\n        "portfolio_mutated": first_receipt.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-035 Oracle Atomic Market Lineage "\n        "Batch Router"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source, encoding="utf-8", newline="\n")
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-035 INSTALLER")
    print(" ORACLE ATOMIC MARKET LINEAGE BATCH")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-035 Oracle Atomic Market Lineage "
        "Batch Router installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_035_oracle_atomic_market_"
        "lineage_batch_router.py"
    )


if __name__ == "__main__":
    main()
